  if (!turn) return {};
  let tree: [string, string, string] | null = null;

  try {
    tree = worktreeTree(cwd);
  } catch {
    tree = null;
  }

  updateState(sid, (st) => {
    enterTurn(st, turn);

    if (tree) st.snapshots[snapshotKey(event)] = tree;
    else st.partial = true;
  });

