await pi.write({path: '/tmp/racy-verify.sh', text: π.script});
const r = await pi.bash({cmd: 'bash /tmp/racy-verify.sh 2>&1', timeout: 120});
return r.output;

const smoke = await pi.bash({cmd: 'cd /Users/pedro/Development/claude-jev && echo \'{"prompt":"hi","transcript_path":""}\' | CLAUDE_CONFIG_DIR="$(mktemp -d)" node --experimental-strip-types src/prompt-router.ts; echo "router exit=$?"; echo "" | node --experimental-strip-types src/compactor.ts rows; echo " rows exit=$?"; echo "{}" | CLAUDE_CONFIG_DIR="$(mktemp -d)" node --experimental-strip-types src/rules.ts; echo " rules exit=$?"', settle: true});
const afk = await pi.bash({cmd: 'cd /Users/pedro/Development/claude-jev/adapters/afk && npm ci -q 2>&1 | tail -2 && npm run build 2>&1 | tail -8', timeout: 240, settle: true});
return JSON.stringify({smoke: smoke.output, afk_tail: afk.output, afk_ok: afk.ok});

const edits = JSON.parse(π.edits) as Record<string, Array<{old: string; new: string}>>;
const results: string[] = [];
for (const [file, list] of Object.entries(edits)) {
  const p = '/Users/pedro/Development/claude-jev/.cursor/skills/verify-claude-jev/' + file;
  let c = await pi.read(p);
  for (const e of list) {
    if (!c.includes(e.old)) { results.push(`${file} MISS: ${e.old.slice(0,55)}`); continue; }
    c = c.replace(e.old, e.new);
  }
  await pi.write({path: p, text: c});
  results.push(`${file} ok`);
}
return results.join('\n');

